<?php

include 'upi.php';

// Random amount between min and max
$amount = rand($minimum, $maximum);

// Get values from included file
$payee_vpa = $upi;       // Payee UPI ID
$note      = $sitename;  // Site or merchant name

// Ensure numeric
$amount = floatval($amount);

// Convert to paise (required for PhonePe)
$initialAmountPaise = intval(round($amount * 100));

// Optional flag
$known = isset($_POST['known']) ? filter_var($_POST['known'], FILTER_VALIDATE_BOOLEAN) : true;

// Build payload
$payload = [
    "contact" => [
        "cbcName"   => "",
        "nickName"  => "",
        "vpa"       => $payee_vpa,
        "type"      => "VPA"
    ],
    "p2pPaymentCheckoutParams" => [
        "note"                        => $note,
        "isByDefaultKnownContact"     => $known,
        "initialAmount"               => $initialAmountPaise,
        "currency"                    => "INR",
        "checkoutType"                => "DEFAULT",
        "transactionContext"          => "p2p"
    ]
];

// Encode payload
$json = json_encode($payload, JSON_UNESCAPED_SLASHES);
$b64  = base64_encode($json);
$data = rawurlencode($b64);

// Construct PhonePe link
$phonepe = "phonepe://native?data={$data}&id=p2ppayment";

